function search(root, target) {
  let node = root;
  while (node !== null) {
    if (target === node.val) return node;      // found it
    if (target < node.val) {
      node = node.left;                        // everything on the right is bigger: skip it
    } else {
      node = node.right;                       // everything on the left is smaller: skip it
    }
  }
  return null;                                 // fell off the tree: not there
}

def search(root, target):
    node = root
    while node is not None:
        if target == node.val:
            return node                 # found it
        if target < node.val:
            node = node.left            # everything on the right is bigger: skip it
        else:
            node = node.right           # everything on the left is smaller: skip it
    return None                         # fell off the tree: not there

TreeNode search(TreeNode root, int target) {
    TreeNode node = root;
    while (node != null) {
        if (target == node.val) return node;   // found it
        if (target < node.val) {
            node = node.left;                   // everything on the right is bigger: skip it
        } else {
            node = node.right;                  // everything on the left is smaller: skip it
        }
    }
    return null;                                // fell off the tree: not there
}

TreeNode* search(TreeNode* root, int target) {
    TreeNode* node = root;
    while (node != nullptr) {
        if (target == node->val) return node;   // found it
        if (target < node->val) {
            node = node->left;                   // everything on the right is bigger: skip it
        } else {
            node = node->right;                  // everything on the left is smaller: skip it
        }
    }
    return nullptr;                              // fell off the tree: not there
}
